import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Batching y rendimiento","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/04-batching-y-rendimiento.md","filePath":"ia/vllm/04-batching-y-rendimiento.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"ia/vllm/04-batching-y-rendimiento.md"};function s(r,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="batching-y-rendimiento" tabindex="-1">Batching y rendimiento <a class="header-anchor" href="#batching-y-rendimiento" aria-label="Permalink to &quot;Batching y rendimiento&quot;">​</a></h1><p>vLLM no espera a “llenar un batch y lanzarlo”: en cada paso de <strong>decode</strong> puede entrar o salir una petición. Eso es <strong>continuous batching</strong>. Junto con <strong>PagedAttention</strong> (KV cache en bloques reutilizables) es lo que sostiene el throughput cuando hay muchas solicitudes a la vez.</p><p>Prefill (procesar el prompt) y decode (un token detrás de otro) no cuestan lo mismo. Una petición larga en prefill puede bloquear el resto; el motor mezcla trabajo para no dejar la GPU quieta. No intentes reproducir eso a mano con <code>generate</code> en un <code>for</code>.</p><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">CLI serve</a> (<code>--gpu-memory-utilization</code>, <code>--max-num-seqs</code>, <code>--max-model-len</code>), <a href="https://docs.vllm.ai/en/latest/design/metrics/" target="_blank" rel="noreferrer">métricas</a>. Ideas de diseño: <a href="https://vllm.ai/blog/2023-06-20-vllm" target="_blank" rel="noreferrer">PagedAttention (blog vLLM)</a>.</p><h2 id="que-tunear-pocos-flags" tabindex="-1">Qué tunear (pocos flags) <a class="header-anchor" href="#que-tunear-pocos-flags" aria-label="Permalink to &quot;Qué tunear (pocos flags)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Efecto</th></tr></thead><tbody><tr><td><code>--gpu-memory-utilization</code></td><td>Fracción de VRAM para esta instancia (default de la CLI: <strong>0.92</strong>). Más alto → más KV → más concurrencia, menos margen para OOM.</td></tr><tr><td><code>--max-num-seqs</code></td><td>Máximo de secuencias en una iteración. Baja si ves OOM o quieres menos latencia a costa de cola.</td></tr><tr><td><code>--max-model-len</code></td><td>Cota de contexto. Menos longitud → más sitio para batch.</td></tr><tr><td><code>--tensor-parallel-size</code></td><td>Parte el modelo entre GPUs (capítulo 5). No es un “turbo” de una GPU.</td></tr></tbody></table><p>No hay un <code>--enable-paged-attention</code>: va siempre. Continuous batching también es el modo de serving, no un extra.</p><p>Ejemplo (ajusta el modelo a tu VRAM):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-0.6B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gpu-memory-utilization</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-num-seqs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-model-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span></span></code></pre></div><h2 id="como-mirar-si-va-bien" tabindex="-1">Cómo mirar si va bien <a class="header-anchor" href="#como-mirar-si-va-bien" aria-label="Permalink to &quot;Cómo mirar si va bien&quot;">​</a></h2><p>Una petición suelta no demuestra nada. Mide con concurrencia:</p><ul><li><strong>TTFT</strong> (<code>vllm:time_to_first_token_seconds</code>): tiempo hasta el primer token.</li><li><strong>ITL / TPOT</strong> (<code>vllm:inter_token_latency_seconds</code>): ritmo entre tokens.</li><li><strong>E2E</strong> (<code>vllm:e2e_request_latency_seconds</code>).</li><li><strong>Cola:</strong> <code>vllm:num_requests_running</code> y peticiones waiting.</li><li><strong>KV:</strong> <code>vllm:kv_cache_usage_perc</code> alto y cola creciente → te faltan bloques (modelo, contexto o utilización).</li></ul><p>Cómo scrapear <code>/metrics</code> está en <a href="./06-observabilidad">Observabilidad</a>.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Subir <code>--gpu-memory-utilization</code> a 0.99 “porque hay margen” y petar al primer pico de contexto.</li><li>Comparar tokens/s de un batch de 1 con un artículo que mide 32 concurrentes.</li><li>Subir <code>-tp</code> en una sola GPU.</li><li>Ignorar que prompts enormes hacen prefill caro aunque <code>max_tokens</code> sea 16.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Fija un SLO (p95 TTFT o tokens/s) y cambia <strong>un</strong> flag cada vez.</li><li>Recorta contexto si el producto no necesita el máximo del card.</li><li>Separa workloads interactivos y batch si se pisan la KV cache.</li><li>Reprodice la mezcla real de longitudes de prompt; un dataset de frases cortas miente.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Sirve un modelo pequeño y lanza 1, luego 8 curls en paralelo. Anota TTFT percibido.</li><li>Baja <code>--max-model-len</code> a la mitad y repite: ¿entra más concurrencia?</li><li>En el siguiente capítulo, localiza <code>vllm:kv_cache_usage_perc</code> en <code>/metrics</code>.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./05-despliegue">Despliegue</a>.</p>`,21)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
